bool ok(TreeNode* n) {
    if (!n) return true;
    if (n->left && n->left->val >= n->val) return false;
    if (n->right && n->right->val <= n->val) return false;
    return ok(n->left) && ok(n->right);
}

long long range_sum(TreeNode* n, int lo, int hi) {
    if (!n) return 0;
    if (n->val < lo) /* ??? */;
    if (n->val > hi) return range_sum(n->left, lo, hi);
    return n->val + range_sum(n->left, lo, hi) + range_sum(n->right, lo, hi);
}
